  "Studio starts this program on your Mac as trusted native code with the environment variables you named. A separate process is crash isolation, not a security sandbox.\nProgram: {program}\nArguments: {args}\nWorking directory: {folder}\nEnvironment variables: {variables}":
    "O Studio inicia este programa no seu Mac como código nativo confiável, com as variáveis de ambiente que você indicou. Um processo separado isola falhas, mas não é um sandbox de segurança.\nPrograma: {program}\nArgumentos: {args}\nPasta de trabalho: {folder}\nVariáveis de ambiente: {variables}",
  "Studio still couldn’t start:": "O Studio ainda não conseguiu iniciar:",
