    "Este arquivo .uproject não é um JSON válido, então o Genex não vai alterá-lo.",
  "This Godot isn't signed by the Godot team, so Genex didn't install it.":
    "Este Godot não é assinado pela equipe do Godot, então o Genex não o instalou.",
  "This Loop": "Este Loop",
  "This Mac can't draw live backgrounds.": "Este Mac não consegue exibir fundos animados.",
  "This Unity Hub isn't signed by Unity, so Genex didn't install it.":
    "Este Unity Hub não foi assinado pela Unity, então o Genex não o instalou.",
