  "This model is not installed in Ollama.": "Este modelo não está instalado no Ollama.",
  "This model is unavailable": "Este modelo não está disponível",
  "This model is unavailable. Check the connection or choose another model.":
    "Este modelo está indisponível. Verifique a conexão ou escolha outro modelo.",
  "This page isn't from the sign-in Genex started.": "Esta página não é do login que o Genex iniciou.",
  "This paste has {count, plural, other {# servers}}. Pick one:":
    "O que você colou tem {count, plural, one {# servidor} other {# servidores}}. Escolha um:",
  "This place is already on Roblox: press Publish an update instead.":
    "Este lugar já está no Roblox: clique em “Publicar atualização”.",
  "This place isn't on Roblox yet: press Publish to Roblox to publish it the first time, as {name}.":
    "Este lugar ainda não está no Roblox: clique em “Publicar no Roblox” para publicá-lo pela primeira vez como {name}.",
  "This plan is no longer waiting for approval.": "Este plano não está mais esperando aprovação.",
  "This plugin has no releases, so Studio takes the newest code. It stays as installed until you update it.":
    "Este plugin não tem versões publicadas, então o Studio pega o código mais recente. Ele fica assim até você atualizar.",
  "This plugin runs trusted code on your Mac.": "Este plugin roda código confiável no seu Mac.",
  "This plugin's package is missing; remove the plugin and install it again":
    "O pacote deste plugin sumiu; remova o plugin e instale-o de novo",
  "This plugin’s plugin.json can’t be used.": "O plugin.json deste plugin não pode ser usado.",
  "This profile cannot store secrets: Studio has no OS encryption here.":
    "Este perfil não pode guardar segredos: o Studio não tem criptografia do sistema aqui.",
  "This profile loads as soon as you’re back online.": "Este perfil carrega assim que você ficar online de novo.",
  "This project has no Packages/manifest.json yet. Open it in Unity once, then set it up again.":
    "Este projeto ainda não tem Packages/manifest.json. Abra-o uma vez no Unity e depois configure de novo.",
  "This project needs Unreal {version}, which isn't installed. Install it from the Epic Games Launcher, or open the project in Unreal to pick another version.":
    "Este projeto precisa do Unreal {version}, que não está instalado. Instale pelo Epic Games Launcher ou abra o projeto no Unreal para escolher outra versão.",
  "This project uses an Unreal Engine built from source, so Genex can't tell which editor opens it. Open it from that engine.":
    "Este projeto usa um Unreal Engine compilado a partir do código-fonte, então o Genex não sabe qual editor o abre. Abra pelo próprio motor.",
  "This project was made with Unreal {made}. Set it up first; that switches it to Unreal {target}.":
    "Este projeto foi feito com o Unreal {made}. Configure primeiro; isso o muda para o Unreal {target}.",
  "This project was saved with Unity {version}, and Genex works with Unity 6 or later. Upgrade it in Unity Hub first.":
    "Este projeto foi salvo com o Unity {version}, e o Genex funciona com o Unity 6 ou mais recente. Atualize-o no Unity Hub primeiro.",
  "This project was saved with Unity {version}: Genex works with Unity 6 or later":
    "Este projeto foi salvo com o Unity {version}: o Genex funciona com o Unity 6 ou mais recente",
  "This project's Packages/manifest.json can't be read as Unity writes it. Fix the file, then set it up again.":
    "O Packages/manifest.json deste projeto não pode ser lido como o Unity o escreve. Corrija o arquivo e depois configure de novo.",
  "This provider cannot prepare a reviewable plan. Choose another model.":
    "Este provedor não consegue preparar um plano para revisão. Escolha outro modelo.",
